files.content:
:root {
  --bg: #2b2b3c;
  --card-bg: #3c3c55;
  --accent: #f5c542;
  --text: #f0f0f0;
  --shadow: #1e1e2a;
  --border: #5a5a7a;
  --radius: 0px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  background-image: linear-gradient(45deg, var(--shadow) 25%, transparent 25%),
    linear-gradient(-45deg, var(--shadow) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--shadow) 75%),
    linear-gradient(-45deg, transparent 75%, var(--shadow) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  image-rendering: pixelated;
}

h1 {
  font-size: 28px;
  text-align: center;
  margin-bottom: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 3px 3px 0 var(--shadow);
}

.input-group {
  margin-bottom: 20px;
}

label, .label-text {
  display: block;
  margin-bottom: 6px;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 1px;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-size: 18px;
  font-family: var(--font);
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  outline: none;
  transition: border-color 0.1s;
}

input[type="number"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--shadow);
}

.tip-buttons {
  display: flex;
  gap: 12px;
}

.tip-btn {
  flex: 1;
  padding: 12px 4px;
  font-size: 18px;
  font-weight: 700;
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  position: relative;
  top: 0;
  left: 0;
}

.tip-btn:hover {
  background: var(--border);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(2px, 2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
}

.results {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 3px dashed var(--border);
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 0;
  font-size: 18px;
}

.result-row .amount {
  font-weight: 700;
  font-size: 22px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--shadow);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 24px;
  }
  .tip-btn {
    font-size: 16px;
    padding: 10px 2px;
  }
  .result-row {
    font-size: 16px;
  }
  .result-row .amount {
    font-size: 20px;
  }
}

(function() {
  const billInput = document.getElementById('bill');
  const peopleInput = document.getElementById('people');
  const tipButtons = document.querySelectorAll('.tip-btn');
  const tipPerPersonEl = document.getElementById('tip-per-person');
  const totalPerPersonEl = document.getElementById('total-per-person');

  let currentTipPercent = 15;

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function updateResults() {
    let bill = parseFloat(billInput.value);
    if (isNaN(bill) || bill < 0) bill = 0;

    let people = parseInt(peopleInput.value, 10);
    if (isNaN(people) || people < 1) people = 1;

    const tipAmount = bill * (currentTipPercent / 100);
    const totalPerPerson = (bill + tipAmount) / people;
    const tipPerPerson = tipAmount / people;

    tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  function setActiveTip(percent) {
    currentTipPercent = percent;
    tipButtons.forEach(btn => {
      const isActive = parseInt(btn.dataset.tip, 10) === percent;
      btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
    updateResults();
  }

  tipButtons.forEach(btn => {
    btn.addEventListener('click', function() {
      setActiveTip(parseInt(this.dataset.tip, 10));
    });
  });

  billInput.addEventListener('input', updateResults);
  peopleInput.addEventListener('input', updateResults);

  // Initialize
  updateResults();
})();
